"""Small route contracts from the deep audit (S1-C): /run keeps the approved
script's language (D4-29), /history timestamps carry their UTC offset (D4-28),
and credit-spending streams report the refreshed balance (D4-19)."""
from datetime import datetime

from conftest import SAMPLE_CSV, post_json, sse_events, upload_csv

from statlee import billing


# ---------------------------------------------------------------- D4-29
def test_run_uses_the_approved_language_for_unchanged_code(client, fake_llm):
    """A Python script generated by /chat, then sent to /run after the user
    switched the dropdown to R, runs as the Python it was approved as, with no
    re-moderation, and the response says which language ran."""
    fake_llm.set('validation', "print('approved python')")
    upload_csv(client, SAMPLE_CSV)
    sse_events(post_json(client, '/chat', {'filename': 'test.csv',
                                           'prompt': 'go',
                                           'language': 'Python'}))
    before = len(fake_llm.calls)
    run = post_json(client, '/run', {'filename': 'test.csv',
                                     'code': "print('approved python')",
                                     'language': 'R'})
    body = run.get_json()
    assert run.status_code == 200, body
    assert body['language'] == 'Python'
    assert body['success'] is True
    assert 'approved python' in body['output']
    assert not any(k == 'code_moderation' for _, k, _ in fake_llm.calls[before:])


def test_run_reports_the_requested_language_when_it_matches(client, fake_llm):
    fake_llm.set('validation', "print('py')")
    upload_csv(client, SAMPLE_CSV)
    sse_events(post_json(client, '/chat', {'filename': 'test.csv',
                                           'prompt': 'go'}))
    body = post_json(client, '/run', {'filename': 'test.csv',
                                      'code': "print('py')",
                                      'language': 'Python'}).get_json()
    assert body['language'] == 'Python'


def test_run_unknown_code_still_uses_the_requested_language(client, fake_llm):
    """Code never approved under any language is moderated for the language
    the client asked for (the D1-7 per-language guard is unchanged)."""
    upload_csv(client, SAMPLE_CSV)
    post_json(client, '/run', {'filename': 'test.csv',
                               'code': "print('new')", 'language': 'R'})
    mods = [t for _, k, t in fake_llm.calls if k == 'code_moderation']
    assert mods and ' R script' in mods[0]


# ---------------------------------------------------------------- D4-28
def test_history_timestamps_carry_the_utc_offset(client):
    post_json(client, '/register', {'email': 'tz@example.com',
                                    'password': 'password123'})
    post_json(client, '/history', {'prompt': 'p'})
    stamp = client.get('/history').get_json()['runs'][0]['created_at']
    assert stamp.endswith('+00:00'), stamp
    assert datetime.fromisoformat(stamp).utcoffset().total_seconds() == 0


def test_to_dict_converts_an_aware_non_utc_stamp_to_utc():
    from datetime import timedelta, timezone

    from statlee.models import AnalysisRun
    run = AnalysisRun(created_at=datetime(2026, 1, 1, 12, 0,
                                          tzinfo=timezone(timedelta(hours=2))))
    assert run.to_dict()['created_at'] == '2026-01-01T10:00:00+00:00'


# ---------------------------------------------------------------- D4-19
def _register(client, app, email, credits):
    from statlee.extensions import db
    from statlee.models import User
    post_json(client, '/register', {'email': email, 'password': 'password123'})
    with app.app_context():
        user = User.query.filter_by(email=email).first()
        user.credits = credits
        db.session.commit()


def _billing(app, on):
    app.config['STATLEE'].billing_enabled = on
    billing.reset_spend()


def test_pro_chat_done_reports_the_balance_after_the_debit(client, app, fake_llm):
    _billing(app, True)
    try:
        _register(client, app, 'pro-balance@example.com', 5)
        upload_csv(client, SAMPLE_CSV)
        events = sse_events(post_json(client, '/chat', {
            'filename': 'test.csv', 'prompt': 'go', 'pro': True}))
        done = next(e for e in events if e.get('type') == 'done')
        assert done['credits_remaining'] == 4
    finally:
        _billing(app, False)


def test_report_done_reports_the_balance_after_the_debit(client, app, fake_llm):
    _billing(app, True)
    try:
        _register(client, app, 'report-balance@example.com', 3)
        events = sse_events(post_json(client, '/generate_report', {
            'output': 'coef=1.2', 'interpretation': 'ok'}))
        done = next(e for e in events if e.get('type') == 'done')
        assert done['credits_remaining'] == 2
    finally:
        _billing(app, False)


def test_failed_stream_error_reports_the_refunded_balance(client, app, fake_llm):
    _billing(app, True)
    try:
        _register(client, app, 'refund-balance@example.com', 5)
        fake_llm.fail('draft', RuntimeError('boom'))
        upload_csv(client, SAMPLE_CSV)
        events = sse_events(post_json(client, '/chat', {
            'filename': 'test.csv', 'prompt': 'go', 'pro': True}))
        err = next(e for e in events if e.get('type') == 'error')
        assert err['credits_remaining'] == 5
    finally:
        _billing(app, False)


def test_no_balance_field_without_billing_or_for_anonymous(client, app, fake_llm):
    upload_csv(client, SAMPLE_CSV)
    events = sse_events(post_json(client, '/chat', {'filename': 'test.csv',
                                                    'prompt': 'go'}))
    done = next(e for e in events if e.get('type') == 'done')
    assert 'credits_remaining' not in done
    _billing(app, True)
    try:                                   # billing on, but anonymous
        events = sse_events(post_json(client, '/chat', {'filename': 'test.csv',
                                                        'prompt': 'go'}))
        done = next(e for e in events if e.get('type') == 'done')
        assert 'credits_remaining' not in done
    finally:
        _billing(app, False)


def test_stream_refund_does_not_log_a_false_failure(client, app, fake_llm,
                                                    caplog):
    """The refund UPDATE committed, then refreshing the request-start User
    outside its session raised and logged "Failed to refund" (found while
    adding D4-19). The refund must complete without that error."""
    import logging
    _billing(app, True)
    try:
        _register(client, app, 'refund-log@example.com', 5)
        fake_llm.fail('draft', RuntimeError('boom'))
        upload_csv(client, SAMPLE_CSV)
        with caplog.at_level(logging.ERROR, logger='statlee.billing'):
            sse_events(post_json(client, '/chat', {
                'filename': 'test.csv', 'prompt': 'go', 'pro': True}))
        assert not [r for r in caplog.records
                    if r.name == 'statlee.billing' and 'refund' in r.getMessage()]
    finally:
        _billing(app, False)
